-- Extend verified CED topic registries for Calculus AB, Calculus BC, and Precalculus.
-- Serving labels remain the downstream scope; topic coverage labeling is deferred.
-- Also corrects the taxonomy topic-code regex applied by taxonomy_label_layer.

begin;

alter table app.taxonomy_topics
  drop constraint if exists taxonomy_topics_topic_code_check;

alter table app.taxonomy_topics
  add constraint taxonomy_topics_topic_code_check
  check (topic_code ~ '^[0-9]+\.[0-9]+$');

create or replace function app.seed_taxonomy_topics(
  _subject_key text,
  _school_year text,
  _source_title text,
  _source_citation text,
  _source_uri text,
  _verified_at timestamptz,
  _topics jsonb
)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  v_source_version uuid;
begin
  if jsonb_typeof(_topics) <> 'array' then
    raise exception 'taxonomy_topics:topics_must_be_array' using errcode = '22023';
  end if;

  insert into app.taxonomy_source_versions (
    subject_key, school_year, source_title, taxonomy_confidence, source_citation, source_uri, verified_at
  ) values (
    _subject_key, _school_year, _source_title, 'verified', _source_citation, _source_uri, _verified_at
  )
  on conflict (subject_key, school_year, source_title) do update
    set taxonomy_confidence = 'verified',
        source_citation = excluded.source_citation,
        source_uri = excluded.source_uri,
        verified_at = excluded.verified_at
  returning taxonomy_source_version into v_source_version;

  insert into app.taxonomy_topics (
    taxonomy_source_version, unit_number, unit_title, topic_code, topic_title
  )
  select
    v_source_version,
    (topic_row.value ->> 'unit_number')::integer,
    topic_row.value ->> 'unit_title',
    topic_row.value ->> 'topic_code',
    topic_row.value ->> 'topic_title'
  from jsonb_array_elements(_topics) as topic_row(value)
  on conflict (taxonomy_source_version, topic_code) do update
    set unit_number = excluded.unit_number,
        unit_title = excluded.unit_title,
        topic_title = excluded.topic_title;

  return v_source_version;
end;
$$;

revoke all on function app.seed_taxonomy_topics(text, text, text, text, text, timestamptz, jsonb)
  from public, anon, authenticated;
grant execute on function app.seed_taxonomy_topics(text, text, text, text, text, timestamptz, jsonb)
  to service_role;

